{"command":"cat << 'EOF' > /workspace/parsers.go
package main

import (
	"archive/zip"
	"bufio"
	"bytes"
	"encoding/csv"
	"encoding/json"
	"encoding/xml"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

func detectFileType(filename string, hintType string) string {
	if hintType != "" {
		ht := strings.ToLower(hintType)
		switch ht {
		case "csv", "tsv", "json", "jsonl", "ndjson", "yaml", "yml", "logfmt", "txt", "xlsx", "xls", "ods", "parquet", "avro", "orc":
			return ht
		case "excel":
			return "xlsx"
		}
		return ht
	}
	ext := strings.TrimPrefix(filepath.Ext(filename), ".")
	return ext
}

func isSupportedType(fileType string) bool {
	switch fileType {
	case "csv", "tsv", "json", "jsonl", "ndjson", "yaml", "yml", "logfmt", "txt", "xlsx", "xls", "ods", "parquet", "avro", "orc":
		return true
	}
	return false
}

func ParseFile(filename string, hintType string) (interface{}, error) {
	fileType := detectFileType(filename, hintType)
	if !isSupportedType(fileType) {
		return nil, fmt.Errorf("Unknown mimetype for file: %s.", filename)
	}

	content, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}

	switch fileType {
	case "csv":
		return parseCSV(content, ',')
	case "tsv":
		return parseCSV(content, '\t')
	case "json":
		return parseJSON(content)
	case "jsonl", "ndjson":
		return parseJSONL(content)
	case "yaml", "yml":
		return parseYAML(content)
	case "logfmt":
		return parseLogfmt(content)
	case "txt":
		return string(content), nil
	case "xlsx", "xls":
		return parseXLSX(filename)
	case "ods":
		return parseODS(filename)
	case "parquet":
		return parseParquet(content)
	case "avro":
		return parseAvro(content)
	case "orc":
		return parseORC(content)
	}

	return nil, fmt.Errorf("Unknown mimetype for file: %s.", filename)
}

func parseCSV(content []byte, comma rune) ([]map[string]interface{}, error) {
	r := csv.NewReader(bytes.NewReader(content))
	r.Comma = comma
	r.FieldsPerRecord = -1
	records, err := r.ReadAll()
	if err != nil {
		return nil, err
	}
	if len(records) == 0 {
		return []map[string]interface{}{}, nil
	}
	headers := records[0]
	var rows []map[string]interface{}
	for i := 1; i < len(records); i++ {
		rec := records[i]
		row := make(map[string]interface{})
		for j, h := range headers {
			if j < len(rec) {
				row[h] = rec[j]
			} else {
				row[h] = ""
			}
		}
		rows = append(rows, row)
	}
	if rows == nil {
		rows = []map[string]interface{}{}
	}
	return rows, nil
}

func parseJSON(content []byte) (interface{}, error) {
	content = bytes.TrimSpace(content)
	if len(content) == 0 {
		return nil, io.EOF
	}
	var data interface{}
	decoder := json.NewDecoder(bytes.NewReader(content))
	decoder.UseNumber()
	if err := decoder.Decode(&data); err != nil {
		return nil, err
	}
	return data, nil
}

func parseJSONL(content []byte) ([]map[string]interface{}, error) {
	var rows []map[string]interface{}
	scanner := bufio.NewScanner(bytes.NewReader(content))
	for scanner.Scan() {
		line := bytes.TrimSpace(scanner.Bytes())
		if len(line) == 0 {
			continue
		}
		var row map[string]interface{}
		decoder := json.NewDecoder(bytes.NewReader(line))
		decoder.UseNumber()
		if err := decoder.Decode(&row); err != nil {
			return nil, err
		}
		rows = append(rows, row)
	}
	if rows == nil {
		rows = []map[string]interface{}{}
	}
	return rows, nil
}

func parseYAML(content []byte) (interface{}, error) {
	content = bytes.TrimSpace(content)
	if len(content) == 0 {
		return nil, io.EOF
	}
	var data interface{}
	if err := yaml.Unmarshal(content, &data); err != nil {
		return nil, err
	}
	return cleanupYAMLData(data), nil
}

func cleanupYAMLData(data interface{}) interface{} {
	switch v := data.(type) {
	case map[string]interface{}:
		m := make(map[string]interface{})
		for k, val := range v {
			m[k] = cleanupYAMLData(val)
		}
		return m
	case map[interface{}]interface{}:
		m := make(map[string]interface{})
		for k, val := range v {
			m[fmt.Sprintf("%v", k)] = cleanupYAMLData(val)
		}
		return m
	case []interface{}:
		var l []interface{}
		for _, val := range v {
			l = append(l, cleanupYAMLData(val))
		}
		return l
	default:
		return v
	}
}

func parseLogfmt(content []byte) ([]map[string]interface{}, error) {
	var rows []map[string]interface{}
	scanner := bufio.NewScanner(bytes.NewReader(content))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		row := make(map[string]interface{})
		i := 0
		for i < len(line) {
			for i < len(line) && line[i] == ' ' {
				i++
			}
			if i >= len(line) {
				break
			}
			keyStart := i
			for i < len(line) && line[i] != '=' && line[i] != ' ' {
