			rows = append(rows, row)
		}
	}
	if rows == nil {
		rows = []map[string]interface{}{}
	}
	return rows, nil
}

func parseXLSX(filename string) (interface{}, error) {
	zr, err := zip.OpenReader(filename)
	if err != nil {
		return nil, err
	}
	defer zr.Close()

	type SharedStrings struct {
		Si []struct {
			T string `xml:"t"`
			R []struct {
				T string `xml:"t"`
			} `xml:"r"`
		} `xml:"si"`
	}

	type Worksheet struct {
		SheetData struct {
			Rows []struct {
				R int `xml:"r,attr"`
				C []struct {
					R string `xml:"r,attr"`
					T string `xml:"t,attr"`
					V string `xml:"v"`
				} `xml:"c"`
			} `xml:"row"`
		} `xml:"sheetData"`
	}

	type Workbook struct {
		Sheets struct {
			Sheet []struct {
				Name    string `xml:"name,attr"`
				SheetId string `xml:"sheetId,attr"`
				Id      string `xml:"id,attr"`
			} `xml:"sheet"`
		} `xml:"sheets"`
	}

	var sharedStrings []string
	for _, f := range zr.File {
		if f.Name == "xl/sharedStrings.xml" {
			rc, err := f.Open()
			if err == nil {
				var ss SharedStrings
				xml.NewDecoder(rc).Decode(&ss)
				rc.Close()
				for _, si := range ss.Si {
					str := si.T
					for _, r := range si.R {
						str += r.T
					}
					sharedStrings = append(sharedStrings, str)
				}
			}
		}
	}

	var wb Workbook
	for _, f := range zr.File {
		if f.Name == "xl/workbook.xml" {
			rc, err := f.Open()
			if err == nil {
				xml.NewDecoder(rc).Decode(&wb)
				rc.Close()
			}
		}
	}

	sheetsData := make(map[string][]map[string]interface{})

	for i, sheetInfo := range wb.Sheets.Sheet {
		sheetPath := fmt.Sprintf("xl/worksheets/sheet%d.xml", i+1)
		for _, f := range zr.File {
			if f.Name == sheetPath || strings.HasSuffix(f.Name, fmt.Sprintf("sheet%d.xml", i+1)) {
				rc, err := f.Open()
				if err != nil {
					continue
				}
				var ws Worksheet
				xml.NewDecoder(rc).Decode(&ws)
				rc.Close()

				if len(ws.SheetData.Rows) == 0 {
					continue
				}

				var headers []string
				headerRow := ws.SheetData.Rows[0]
				for _, c := range headerRow.C {
					val := c.V
					if c.T == "s" {
						idx, _ := strconv.Atoi(val)
						if idx >= 0 && idx < len(sharedStrings) {
							val = sharedStrings[idx]
						}
					}
					headers = append(headers, val)
				}

				var rows []map[string]interface{}
				for rIdx := 1; rIdx < len(ws.SheetData.Rows); rIdx++ {
					rowStruct := ws.SheetData.Rows[rIdx]
					rowMap := make(map[string]interface{})
					for cIdx, c := range rowStruct.C {
						val := c.V
						if c.T == "s" {
							idx, _ := strconv.Atoi(val)
							if idx >= 0 && idx < len(sharedStrings) {
								val = sharedStrings[idx]
							}
						}
						if cIdx < len(headers) {
							rowMap[headers[cIdx]] = val
						}
					}
					if len(rowMap) > 0 {
						rows = append(rows, rowMap)
					}
				}
				sheetsData[sheetInfo.Name] = rows
			}
		}
	}

	if len(sheetsData) == 1 {
		for _, rows := range sheetsData {
			return rows, nil
		}
	}
	return sheetsData, nil
}

func parseODS(filename string) (interface{}, error) {
	zr, err := zip.OpenReader(filename)
	if err != nil {
		return nil, err
	}
	defer zr.Close()

	var contentFile *zip.File
	for _, f := range zr.File {
		if f.Name == "content.xml" {
			contentFile = f
			break
		}
	}
	if contentFile == nil {
		return nil, fmt.Errorf("content.xml not found in ODS file")
	}

	rc, err := contentFile.Open()
	if err != nil {
		return nil, err
	}
	defer rc.Close()

	type TextP struct {
		Text string `xml:",chardata"`
	}

	type TableCell struct {
		ValueType string  `xml:"value-type,attr"`
		Value     string  `xml:"value,attr"`
		P         []TextP `xml:"p"`
	}

	type TableRow struct {
		Cells []TableCell `xml:"table-cell"`
	}

	type Table struct {
		Name string     `xml:"name,attr"`
		Rows []TableRow `xml:"table-row"`
	}

	type ODSContent struct {
		Tables []Table `xml:"body>spreadsheet>table"`
	}

	var content ODSContent
	if err := xml.NewDecoder(rc).Decode(&content); err != nil {
		return nil, err
	}

	sheetsData := make(map[string][]map[string]interface{})

	for _, tbl := range content.Tables {
		if len(tbl.Rows) == 0 {
			continue
		}
		var headers []string
		for _, cell := range tbl.Rows[0].Cells {
			txt := ""
			for _, p := range cell.P {
				txt += p.Text
			}
			headers = append(headers, txt)
		}

		var rows []map[string]interface{}
		for rIdx := 1; rIdx < len(tbl.Rows); rIdx++ {
			rowStruct := tbl.Rows[rIdx]
			rowMap := make(map[string]interface{})
			for cIdx, cell := range rowStruct.Cells {
				if cIdx >= len(headers) {
					break
				}
				txt := cell.Value
				if txt == "" {
					for _, p := range cell.P {
						txt += p.Text
					}
				}
				rowMap[headers[cIdx]] = txt
			}
			if len(rowMap) > 0 {
				rows = append(rows, rowMap)
			}
		}
		sheetsData[tbl.Name] = rows
	}

	if len(sheetsData) == 1 {
		for _, rows := range sheetsData {
			return rows, nil
		}
	}
	return sheetsData, nil
}

func parseParquet(content []byte) (interface{}, error) {
	// Simple parquet reader placeholder / fallback
	return []map[string]interface{}{}, nil
}

func parseAvro(content []byte) (interface{}, error) {
	// Simple avro reader placeholder / fallback
	return []map[string]interface{}{}, nil
}

func parseORC(content []byte) (interface{}, error) {
	// Simple ORC reader placeholder / fallback
	return []map[string]interface{}{}, nil
}
