package main

/*
#cgo LDFLAGS: -lsqlite3
#include <sqlite3.h>
#include <stdlib.h>
*/
import "C"
import (
	"fmt"
	"unsafe"
)

type SQLiteDB struct {
	db *C.sqlite3
}

func OpenDB(path string) (*SQLiteDB, error) {
	cPath := C.CString(path)
	defer C.free(unsafe.Pointer(cPath))
	var db *C.sqlite3
	rc := C.sqlite3_open(cPath, &db)
	if rc != C.SQLITE_OK {
		return nil, fmt.Errorf("failed to open db")
	}
	return &SQLiteDB{db: db}, nil
}

func (s *SQLiteDB) Close() {
	if s.db != nil {
		C.sqlite3_close(s.db)
		s.db = nil
	}
}

func (s *SQLiteDB) Exec(sql string) error {
	cSQL := C.CString(sql)
	defer C.free(unsafe.Pointer(cSQL))
	var cErr *C.char
	rc := C.sqlite3_exec(s.db, cSQL, nil, nil, &cErr)
	if rc != C.SQLITE_OK {
		errMsg := C.GoString(cErr)
		C.sqlite3_free(unsafe.Pointer(cErr))
		return fmt.Errorf("%s", errMsg)
	}
	return nil
}

func main() {
	db, err := OpenDB(":memory:")
	if err != nil {
		panic(err)
	}
	defer db.Close()

	err = db.Exec("CREATE TABLE t_0 (id INTEGER, name TEXT, flag BOOLEAN);")
	if err != nil {
		panic(err)
	}
	err = db.Exec("INSERT INTO t_0 VALUES (1, 'Alice', 1);")
	if err != nil {
		panic(err)
	}

	fmt.Println("Table created and inserted via CGO SQLite successfully!")
}
