func FormatJSONOutput(rows []map[string]interface{}) string {
	if len(rows) == 0 {
		return "[]\n"
	}

	var rowStrs []string
	for _, row := range rows {
		buf, _ := json.Marshal(row)
		rowStrs = append(rowStrs, string(buf))
	}

	if len(rowStrs) == 1 {
		return "[" + rowStrs[0] + "]\n"
	}

	return "[\n" + strings.Join(rowStrs, ",\n") + "]\n"
}

func FormatPrettyOutput(rows []map[string]interface{}) string {
	if len(rows) == 0 {
		return "(0 rows)\n"
	}

	colSet := make(map[string]bool)
	for _, r := range rows {
		for k := range r {
			colSet[k] = true
		}
	}

	var cols []string
	for k := range colSet {
		cols = append(cols, k)
	}
	sort.Strings(cols)

	widths := make(map[string]int)
	for _, col := range cols {
		widths[col] = len(col)
	}

	cellMatrix := make([][]string, len(rows))
	for rIdx, r := range rows {
		rowCells := make([]string, len(cols))
		for cIdx, col := range cols {
			val := r[col]
			cellStr := formatPrettyValue(val)
			rowCells[cIdx] = cellStr
			if len(cellStr) > widths[col] {
				widths[col] = len(cellStr)
			}
		}
		cellMatrix[rIdx] = rowCells
	}

	var borderParts []string
	for _, col := range cols {
		borderParts = append(borderParts, strings.Repeat("-", widths[col]+2))
	}
	border := "+" + strings.Join(borderParts, "+") + "+"

	var headerParts []string
	for _, col := range cols {
		w := widths[col]
		padLeft := (w - len(col)) / 2
		padRight := w - len(col) - padLeft
		headerParts = append(headerParts, fmt.Sprintf(" %s%s%s ", strings.Repeat(" ", padLeft), col, strings.Repeat(" ", padRight)))
	}
	headerLine := "|" + strings.Join(headerParts, "|") + "|"

	var sb strings.Builder
	sb.WriteString(border)
	sb.WriteString("\n")
	sb.WriteString(headerLine)
	sb.WriteString("\n")
	sb.WriteString(border)
	sb.WriteString("\n")

	for _, rowCells := range cellMatrix {
		var rowParts []string
		for cIdx, cellStr := range rowCells {
			col := cols[cIdx]
			w := widths[col]
			padLeft := (w - len(cellStr)) / 2
			padRight := w - len(cellStr) - padLeft
			rowParts = append(rowParts, fmt.Sprintf(" %s%s%s ", strings.Repeat(" ", padLeft), cellStr, strings.Repeat(" ", padRight)))
		}
		sb.WriteString("|")
		sb.WriteString(strings.Join(rowParts, "|"))
		sb.WriteString("|\n")
	}

	sb.WriteString(border)
	sb.WriteString("\n")

	if len(rows) == 1 {
		sb.WriteString("(1 row)\n")
	} else {
		sb.WriteString(fmt.Sprintf("(%d rows)\n", len(rows)))
	}

	return sb.String()
}

func formatPrettyValue(val interface{}) string {
	if val == nil {
		return "null"
	}
	switch v := val.(type) {
	case bool:
		if v {
			return "true"
		}
		return "false"
	case string:
		return v
	case float64:
		return fmt.Sprintf("%v", v)
	case int64:
		return fmt.Sprintf("%d", v)
	case int:
		return fmt.Sprintf("%d", v)
	default:
		buf, _ := json.Marshal(v)
		return string(buf)
	}
}
EOF"}

