	Scalar string                 `json:"scalar,omitempty"`
	Array  *SchemaNode            `json:"array,omitempty"`
	Object map[string]*SchemaNode `json:"object,omitempty"`
	Varied []*SchemaNode          `json:"varied,omitempty"`
}

func InferSchema(val interface{}) *SchemaNode {
	if val == nil {
		return &SchemaNode{Kind: "unknown"}
	}

	switch v := val.(type) {
	case bool:
		return &SchemaNode{Kind: "scalar", Scalar: "boolean"}
	case string:
		return &SchemaNode{Kind: "scalar", Scalar: "string"}
	case float64, int, int64, json.Number:
		return &SchemaNode{Kind: "scalar", Scalar: "number"}
	case map[string]interface{}:
		objMap := make(map[string]*SchemaNode)
		for k, child := range v {
			objMap[k] = InferSchema(child)
		}
		return &SchemaNode{Kind: "object", Object: objMap}
	case []interface{}:
		if len(v) == 0 {
			return &SchemaNode{Kind: "array", Array: &SchemaNode{Kind: "unknown"}}
		}
		var elemSchema *SchemaNode
		for _, child := range v {
			s := InferSchema(child)
			if elemSchema == nil {
				elemSchema = s
			} else {
				elemSchema = MergeSchemas(elemSchema, s)
			}
		}
		return &SchemaNode{Kind: "array", Array: elemSchema}
	case []map[string]interface{}:
		var slice []interface{}
		for _, item := range v {
			slice = append(slice, item)
		}
		return InferSchema(slice)
	}

	return &SchemaNode{Kind: "scalar", Scalar: "string"}
}

func MergeSchemas(a, b *SchemaNode) *SchemaNode {
	if a == nil {
		return b
	}
	if b == nil {
		return a
	}
	if a.Kind == "unknown" {
		return b
	}
	if b.Kind == "unknown" {
		return a
	}
	if a.Kind == b.Kind {
		if a.Kind == "scalar" {
			if a.Scalar == b.Scalar {
				return a
			}
			return &SchemaNode{
				Kind: "varied",
				Varied: []*SchemaNode{
					a,
					b,
				},
			}
		}
		if a.Kind == "object" {
			merged := make(map[string]*SchemaNode)
			keys := make(map[string]bool)
			for k := range a.Object {
				keys[k] = true
			}
			for k := range b.Object {
				keys[k] = true
			}
			for k := range keys {
				sA := a.Object[k]
				sB := b.Object[k]
				if sA == nil {
					sA = &SchemaNode{Kind: "scalar", Scalar: "null"}
				}
				if sB == nil {
					sB = &SchemaNode{Kind: "scalar", Scalar: "null"}
				}
				merged[k] = MergeSchemas(sA, sB)
			}
			return &SchemaNode{Kind: "object", Object: merged}
		}
		if a.Kind == "array" {
			return &SchemaNode{Kind: "array", Array: MergeSchemas(a.Array, b.Array)}
		}
	}
	return &SchemaNode{
		Kind: "varied",
		Varied: []*SchemaNode{
			a,
			b,
		},
	}
}

func SchemaToJSON(s *SchemaNode) (string, error) {
	buf, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return "", err
	}
	return string(buf), nil
}

func GetSchemaForFile(filename string, hintType string) (string, error) {
	parsed, err := ParseFile(filename, hintType)
	if err != nil {
		return "", err
	}
	schema := InferSchema(parsed)
	return SchemaToJSON(schema)
}
EOF

