package main

/*
#cgo LDFLAGS: -lsqlite3
#include <sqlite3.h>
#include <stdlib.h>
*/
import "C"
import (
	"crypto/sha1"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"unsafe"
)

type SQLiteDB struct {
	db *C.sqlite3
}

func OpenDB(path string) (*SQLiteDB, error) {
	cPath := C.CString(path)
	defer C.free(unsafe.Pointer(cPath))
	var db *C.sqlite3
	rc := C.sqlite3_open(cPath, &db)
	if rc != C.SQLITE_OK {
		return nil, fmt.Errorf("failed to open sqlite db")
	}
	return &SQLiteDB{db: db}, nil
}

func (s *SQLiteDB) Close() {
	if s.db != nil {
		C.sqlite3_close(s.db)
		s.db = nil
	}
}

func (s *SQLiteDB) Exec(sql string) error {
	cSQL := C.CString(sql)
	defer C.free(unsafe.Pointer(cSQL))
	var cErr *C.char
	rc := C.sqlite3_exec(s.db, cSQL, nil, nil, &cErr)
	if rc != C.SQLITE_OK {
		errMsg := "sqlite error"
		if cErr != nil {
			errMsg = C.GoString(cErr)
			C.sqlite3_free(unsafe.Pointer(cErr))
		}
		return fmt.Errorf("%s", errMsg)
	}
	return nil
}

func FlattenMap(m map[string]interface{}, prefix string) map[string]interface{} {
	res := make(map[string]interface{})
	for k, v := range m {
		fullKey := k
		if prefix != "" {
			fullKey = prefix + "." + k
		}
		if childMap, ok := v.(map[string]interface{}); ok {
			flatChild := FlattenMap(childMap, fullKey)
			for fk, fv := range flatChild {
				res[fk] = fv
			}
		} else if sliceVal, ok := v.([]interface{}); ok {
			buf, _ := json.Marshal(sliceVal)
			res[fullKey] = string(buf)
		} else {
			res[fullKey] = v
		}
	}
	return res
}

func (s *SQLiteDB) ImportTable(tableName string, data []map[string]interface{}) error {
	if len(data) == 0 {
		sql := fmt.Sprintf("CREATE TABLE IF NOT EXISTS %s (dummy TEXT);", tableName)
		return s.Exec(sql)
	}

	var flatRows []map[string]interface{}
	colTypes := make(map[string]string)
	colOrderMap := make(map[string]int)

	for _, rawRow := range data {
		flatRow := FlattenMap(rawRow, "")
		flatRows = append(flatRows, flatRow)
		for k, v := range flatRow {
			if _, exists := colOrderMap[k]; !exists {
				colOrderMap[k] = len(colOrderMap)
			}
			if v != nil {
				currType := colTypes[k]
				switch v.(type) {
				case bool:
					if currType == "" {
						colTypes[k] = "BOOLEAN"
					}
				case float64, int, int64, json.Number:
					if currType == "" || currType == "BOOLEAN" {
						colTypes[k] = "NUMERIC"
					}
				default:
					colTypes[k] = "TEXT"
				}
			}
		}
	}

	var cols []string
	for k := range colOrderMap {
		cols = append(cols, k)
	}
	sort.Strings(cols)

	for _, k := range cols {
		if colTypes[k] == "" {
			colTypes[k] = "TEXT"
		}
	}

	var colDefs []string
	for _, col := range cols {
		colDefs = append(colDefs, fmt.Sprintf("%s %s", quoteIdent(col), colTypes[col]))
	}

	createSQL := fmt.Sprintf("CREATE TABLE %s (%s);", tableName, strings.Join(colDefs, ", "))
	if err := s.Exec(createSQL); err != nil {
		return err
	}

	if len(flatRows) == 0 {
		return nil
	}

	var placeholders []string
	var quotedCols []string
	for _, col := range cols {
		quotedCols = append(quotedCols, quoteIdent(col))
		placeholders = append(placeholders, "?")
	}

	insertSQL := fmt.Sprintf("INSERT INTO %s (%s) VALUES (%s);", tableName, strings.Join(quotedCols, ", "), strings.Join(placeholders, ", "))
	cInsertSQL := C.CString(insertSQL)
	defer C.free(unsafe.Pointer(cInsertSQL))

	var stmt *C.sqlite3_stmt
	rc := C.sqlite3_prepare_v2(s.db, cInsertSQL, -1, &stmt, nil)
	if rc != C.SQLITE_OK {
		return fmt.Errorf("prepare failed: %s", C.GoString(C.sqlite3_errmsg(s.db)))
	}
	defer C.sqlite3_finalize(stmt)

	for _, row := range flatRows {
		C.sqlite3_reset(stmt)
		C.sqlite3_clear_bindings(stmt)

		for i, col := range cols {
			val := row[col]
			colIdx := C.int(i + 1)
			if val == nil {
				C.sqlite3_bind_null(stmt, colIdx)
			} else {
				switch v := val.(type) {
				case bool:
					bVal := C.int(0)
					if v {
						bVal = 1
					}
					C.sqlite3_bind_int(stmt, colIdx, bVal)
				case int:
					C.sqlite3_bind_int64(stmt, colIdx, C.sqlite3_int64(v))
				case int64:
					C.sqlite3_bind_int64(stmt, colIdx, C.sqlite3_int64(v))
				case float64:
					C.sqlite3_bind_double(stmt, colIdx, C.double(v))
				case json.Number:
					if f, err := v.Float64(); err == nil {
						C.sqlite3_bind_double(stmt, colIdx, C.double(f))
					} else {
						strVal := C.CString(v.String())
						C.sqlite3_bind_text(stmt, colIdx, strVal, -1, C.SQLITE_TRANSIENT)
						C.free(unsafe.Pointer(strVal))
					}
				case string:
					strVal := C.CString(v)
					C.sqlite3_bind_text(stmt, colIdx, strVal, -1, C.SQLITE_TRANSIENT)
					C.free(unsafe.Pointer(strVal))
				default:
					buf, _ := json.Marshal(v)
					strVal := C.CString(string(buf))
					C.sqlite3_bind_text(stmt, colIdx, strVal, -1, C.SQLITE_TRANSIENT)
					C.free(unsafe.Pointer(strVal))
				}
			}
		}
		C.sqlite3_step(stmt)
	}

	return nil
}

func quoteIdent(s string) string {
	return `"` + strings.ReplaceAll(s, `"`, `""`) + `"`
}

func TransformQuery(query string) string {
	q := strings.ReplaceAll(query, "{}", "{0}")
	re := regexp.MustCompile(`\{(\d+)\}`)
	q = re.ReplaceAllString(q, "t_$1")
	return q
}

func (s *SQLiteDB) Query(query string) ([]map[string]interface{}, error) {
	cQuery := C.CString(query)
	defer C.free(unsafe.Pointer(cQuery))

	var stmt *C.sqlite3_stmt
	rc := C.sqlite3_prepare_v2(s.db, cQuery, -1, &stmt, nil)
	if rc != C.SQLITE_OK {
		errMsg := C.GoString(C.sqlite3_errmsg(s.db))
		return nil, fmt.Errorf("%s", errMsg)
	}
	defer C.sqlite3_finalize(stmt)

	numCols := int(C.sqlite3_column_count(stmt))
	colNames := make([]string, numCols)
	colTypes := make([]string, numCols)

	for i := 0; i < numCols; i++ {
		cName := C.sqlite3_column_name(stmt, C.int(i))
		colNames[i] = C.GoString(cName)
		cDecl := C.sqlite3_column_decltype(stmt, C.int(i))
		if cDecl != nil {
			colTypes[i] = strings.ToUpper(C.GoString(cDecl))
		}
	}

	var results []map[string]interface{}

	for {
		stepRc := C.sqlite3_step(stmt)
		if stepRc == C.SQLITE_DONE {
			break
		}
		if stepRc != C.SQLITE_ROW {
			errMsg := C.GoString(C.sqlite3_errmsg(s.db))
			return nil, fmt.Errorf("%s", errMsg)
		}

		row := make(map[string]interface{})
		for i := 0; i < numCols; i++ {
			cIdx := C.int(i)
			colType := C.sqlite3_column_type(stmt, cIdx)
			declType := colTypes[i]

			if colType == C.SQLITE_NULL {
				row[colNames[i]] = nil
			} else if declType == "BOOLEAN" || declType == "BOOL" {
				val := int(C.sqlite3_column_int64(stmt, cIdx))
				row[colNames[i]] = (val != 0)
			} else if colType == C.SQLITE_INTEGER {
				val := int64(C.sqlite3_column_int64(stmt, cIdx))
				row[colNames[i]] = val
			} else if colType == C.SQLITE_FLOAT {
				val := float64(C.sqlite3_column_double(stmt, cIdx))
				row[colNames[i]] = val
			} else {
				cText := C.sqlite3_column_text(stmt, cIdx)
				text := ""
				if cText != nil {
					text = C.GoString((*C.char)(unsafe.Pointer(cText)))
				}
				row[colNames[i]] = text
			}
		}
		results = append(results, row)
	}

	if results == nil {
		results = []map[string]interface{}{}
	}
	return results, nil
}

func GetCacheDBPath(filenames []string) string {
	hasher := sha1.New()
	for _, fn := range filenames {
		fi, err := os.Stat(fn)
		if err == nil {
			hasher.Write([]byte(fmt.Sprintf("%s:%d:%d", fn, fi.Size(), fi.ModTime().UnixNano())))
		} else {
			hasher.Write([]byte(fn))
		}
	}
	hashStr := hex.EncodeToString(hasher.Sum(nil))
	return filepath.Join(os.TempDir(), fmt.Sprintf("dsq-cache-%s.db", hashStr))
}
