)

const HelpText = `dsq (Version latest) - commandline SQL engine for data files

Usage:  dsq [file...] $query
        dsq $file [query]
        cat $file | dsq -s $filetype [query]
        dsq $file -f $queryfile

dsq is a tool for running SQL on one or more data files. It uses
SQLite's SQL dialect. Files as tables are accessible via "{N}" where N
is the 0-based index of the file in the commandline.

The shorthand "{}" is replaced with "{0}".

Examples:

    # This simply dumps the CSV as JSON
    $ dsq test.csv

    # This dumps the first 10 rows of the parquet file as JSON.
    $ dsq data.parquet "SELECT * FROM {} LIMIT 10"

    # This joins two datasets of differing origin types (CSV and JSON).
    $ dsq testdata/join/users.csv testdata/join/ages.json \
          "select {0}.name, {1}.age from {0} join {1} on {0}.id = {1}.id"

See the repo for more details: https://github.com/multiprocessio/dsq`

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run() error {
	args := os.Args[1:]

	var flagPretty bool
	var flagSchema bool
	var flagCache bool
	var flagInteractive bool
	var flagStream string
	var flagFile string

	var positional []string

	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "-v" || arg == "--version" {
			fmt.Fprintln(os.Stderr, "dsq latest")
			os.Exit(0)
		} else if arg == "-h" || arg == "--help" {
			fmt.Fprintln(os.Stderr, HelpText)
			os.Exit(0)
		} else if arg == "-p" || arg == "--pretty" {
			flagPretty = true
		} else if arg == "-c" || arg == "--schema" {
			flagSchema = true
		} else if arg == "-C" || arg == "--cache" {
			flagCache = true
		} else if arg == "-i" || arg == "--interactive" {
			flagInteractive = true
		} else if arg == "-s" || arg == "--stream" {
			if i+1 < len(args) {
				flagStream = args[i+1]
				i++
			}
		} else if strings.HasPrefix(arg, "-s=") {
			flagStream = strings.TrimPrefix(arg, "-s=")
		} else if arg == "-f" || arg == "--file" {
			if i+1 < len(args) {
				flagFile = args[i+1]
				i++
			}
		} else if strings.HasPrefix(arg, "-f=") {
			flagFile = strings.TrimPrefix(arg, "-f=")
		} else if strings.HasPrefix(arg, "--file=") {
			flagFile = strings.TrimPrefix(arg, "--file=")
		} else {
			positional = append(positional, arg)
		}
		i++
	}

	stat, _ := os.Stdin.Stat()
	isStdin := (stat.Mode() & os.ModeCharDevice) == 0

	var files []string
	var query string

	if isStdin {
		if flagStream == "" {
			return fmt.Errorf("No input files.")
		}
		content, err := io.ReadAll(os.Stdin)
		if err != nil {
			return err
		}
		tmpFile, err := os.CreateTemp("", fmt.Sprintf("dsq-stdin*.%s", flagStream))
		if err != nil {
			return err
		}
		defer os.Remove(tmpFile.Name())
		tmpFile.Write(content)
		tmpFile.Close()

		files = []string{tmpFile.Name()}
		if flagFile != "" {
			qBuf, err := os.ReadFile(flagFile)
			if err != nil {
				return err
			}
			query = string(qBuf)
		} else if len(positional) > 0 {
			query = positional[0]
		} else {
			query = "SELECT * FROM {}"
		}
	} else {
		if len(positional) == 0 {
			return fmt.Errorf("No input files.")
		}

		if flagFile != "" {
			qBuf, err := os.ReadFile(flagFile)
			if err != nil {
				return err
			}
			query = string(qBuf)
			files = positional
		} else {
			if len(positional) == 1 {
				files = positional
				query = "SELECT * FROM {}"
			} else {
				files = positional[:len(positional)-1]
				query = positional[len(positional)-1]
			}
		}
	}

	if flagSchema {
		schemaStr, err := GetSchemaForFile(files[0], flagStream)
		if err != nil {
			return err
		}
		fmt.Println(schemaStr)
		return nil
	}

	noExplicitQuery := (flagFile == "" && len(positional) == 1 && !isStdin)

	var datasets []interface{}
	for _, fn := range files {
		data, err := ParseFile(fn, flagStream)
		if err != nil {
			return err
		}
		datasets = append(datasets, data)
	}

	if noExplicitQuery {
		firstData := datasets[0]
		if _, isArray := firstData.([]map[string]interface{}); !isArray {
			if _, isMap := firstData.(map[string]interface{}); isMap {
				if !flagPretty {
					buf, err := json.Marshal(firstData)
					if err != nil {
						return err
					}
					fmt.Println(string(buf))
					return nil
				}
			}
		}
	}

	dbPath := ":memory:"
	if flagCache {
		dbPath = GetCacheDBPath(files)
	}

	db, err := OpenDB(dbPath)
	if err != nil {
		return err
	}
	defer db.Close()

	for idx, dataset := range datasets {
		tableName := fmt.Sprintf("t_%d", idx)
		var rows []map[string]interface{}
		if rSlice, ok := dataset.([]map[string]interface{}); ok {
			rows = rSlice
		} else if rSliceAny, ok := dataset.([]interface{}); ok {
			for _, item := range rSliceAny {
				if itemMap, ok := item.(map[string]interface{}); ok {
					rows = append(rows, itemMap)
				}
			}
		} else {
			return fmt.Errorf("Input is not an array of objects: %s.", files[idx])
		}

		if err := db.ImportTable(tableName, rows); err != nil {
			return err
		}
	}

	if flagInteractive {
		return runREPL(db, flagPretty)
	}

	finalQuery := TransformQuery(query)
	results, err := db.Query(finalQuery)
	if err != nil {
		return err
	}

	if flagPretty {
		fmt.Print(FormatPrettyOutput(results))
	} else {
		fmt.Print(FormatJSONOutput(results))
	}

	return nil
}

func runREPL(db *SQLiteDB, pretty bool) error {
	scanner := bufio.NewScanner(os.Stdin)
	for {
		if !scanner.Scan() {
			break
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		finalQuery := TransformQuery(line)
		results, err := db.Query(finalQuery)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			continue
		}
		if pretty {
			fmt.Print(FormatPrettyOutput(results))
		} else {
			fmt.Print(FormatJSONOutput(results))
		}
	}
	return nil
}
